{
  "name": "BioShake微孔板加热振荡器",
  "name_en": "BioShake microplate heater shaker",
  "manufacturer": "QInstruments",
  "description": "这是一种实验室微孔板加热振荡器，可对板式样品进行控温并同时振荡混匀。它常用于样品孵育、反应混合、酶反应、核酸与蛋白相关实验等需要稳定温度和持续摇匀的流程，部分机型还支持锁板与主动冷却功能。",
  "description_en": "This is a laboratory microplate heater shaker that provides temperature control and shaking for plate-based samples. It is commonly used for sample incubation, reaction mixing, enzymatic workflows, and nucleic acid or protein-related assays that require stable heating and continuous agitation. Some models also support plate locking and active cooling.",
  "actions": [
    {
      "action_name": "auto-deactivate",
      "description": "关闭温控",
      "description_en": "stop temperature control"
    },
    {
      "action_name": "auto-home",
      "description": "回到初始位置",
      "description_en": "move the device to its home position"
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定样品板",
      "description_en": "lock the plate in place"
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备",
      "description_en": "reset the device"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度",
      "description_en": "set the target temperature"
    },
    {
      "action_name": "auto-setup",
      "description": "初始化设备并准备运行",
      "description_en": "initialize the device and prepare it for operation"
    },
    {
      "action_name": "auto-shake",
      "description": "以设定速度开始振荡",
      "description_en": "start shaking at the specified speed"
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备运行",
      "description_en": "stop device operation"
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡",
      "description_en": "stop shaking"
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁样品板",
      "description_en": "unlock the plate"
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取是否支持锁板",
      "description_en": "get whether plate locking is supported"
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取是否支持主动冷却",
      "description_en": "get whether active cooling is supported"
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度",
      "description_en": "get the current temperature"
    }
  ],
  "tag_hints": [
    "microplate heater shaker",
    "plate incubation",
    "temperature control",
    "orbital shaking",
    "sample mixing",
    "plate locking",
    "active cooling"
  ]
}

